function inside(p,q){let yes=false;for(let i=0,j=p.length-1;i<p.length;j=i++){if(on(p[j],p[i],q))return true;if((p[i].y>q.y)!==(p[j].y>q.y)&&q.x<(p[j].x-p[i].x)*(q.y-p[i].y)/(p[j].y-p[i].y)+p[i].x)yes=!yes}return yes}
function rectInside(p,x,y,w,h){const corners=[{x,y},{x:x+w,y},{x:x+w,y:y+h},{x,y:y+h}];if(!corners.every(q=>inside(p,q)))return false; // Reject concave cutouts crossing the rectangle interior.
for(let i=0;i<p.length;i++){const a=p[i],b=p[(i+1)%p.length];const ts=[0,1];for(const xx of [x,x+w])if(b.x!==a.x){const t=(xx-a.x)/(b.x-a.x);if(t>0&&t<1)ts.push(t)}for(const yy of [y,y+h])if(b.y!==a.y){const t=(yy-a.y)/(b.y-a.y);if(t>0&&t<1)ts.push(t)}ts.sort((a,b)=>a-b);for(let j=1;j<ts.length;j++){const t=(ts[j-1]+ts[j])/2,q={x:a.x+t*(b.x-a.x),y:a.y+t*(b.y-a.y)};if(q.x>x+EPS&&q.x<x+w-EPS&&q.y>y+EPS&&q.y<y+h-EPS)return false}}return true}
const rect=(w,d)=>[{x:0,y:0},{x:w,y:0},{x:w,y:d},{x:0,y:d}];
function template(kind,w=4200,d=3400){if(kind==='L')return [{x:0,y:0},{x:w,y:0},{x:w,y:Math.round(d*.55)},{x:Math.round(w*.55),y:Math.round(d*.55)},{x:Math.round(w*.55),y:d},{x:0,y:d}];if(kind==='U')return [{x:0,y:0},{x:w,y:0},{x:w,y:d},{x:Math.round(w*.7),y:d},{x:Math.round(w*.7),y:Math.round(d*.45)},{x:Math.round(w*.3),y:Math.round(d*.45)},{x:Math.round(w*.3),y:d},{x:0,y:d}];if(kind==='skos')return [{x:Math.round(w*.18),y:0},{x:Math.round(w*.82),y:0},{x:w,y:d},{x:0,y:d}];return rect(w,d)}
const edge=(r,i)=>{const a=r.points[i],b=r.points[(i+1)%r.points.length];return {a,b,len:Math.hypot(b.x-a.x,b.y-a.y),dx:b.x-a.x,dy:b.y-a.y}};
