function align(a,wa,b,wb,t,offset){const ea=edge(a,wa),eb=edge(b,wb),ux=ea.dx/ea.len,uy=ea.dy/ea.len,vx=eb.dx/eb.len,vy=eb.dy/eb.len;if(Math.abs(ux*vy-uy*vx)>.001||ux*vx+uy*vy>-.999)throw Error('Wybierz ściany równoległe skierowane przeciwnie. Obrót pokoju wykonaj w edycji obrysu.');if(offset>=ea.len||offset+eb.len<=0)throw Error('Ściany nie mają wspólnego odcinka.');return {x:a.x+ea.a.x+ux*offset+uy*t-eb.b.x,y:a.y+ea.a.y+uy*offset-ux*t-eb.b.y}}
